function TrailReviewCommentsSection({
  comments,
  onOpenThread,
}: {
  comments: TrailComment[]
  onOpenThread: () => void
}) {
  const [showResolved, setShowResolved] = useState(false)
  const unresolvedComments = useMemo(() => comments.filter((comment) => !comment.resolved), [comments])
  const resolvedComments = useMemo(() => comments.filter((comment) => comment.resolved), [comments])
  const visibleComments = showResolved ? comments : unresolvedComments
  const emptyText = comments.length === 0 ? "No review comments yet." : "No unresolved review comments."

  return (
    <section className="space-y-3">
      <div className="flex items-center justify-between gap-3">
        <SectionHeader title="Review comments" count={visibleComments.length} />
        {resolvedComments.length > 0 ? (
          <Button
            size="small"
            variant="ghost"
            condensed
            onClick={() => setShowResolved((value) => !value)}
          >
            {showResolved ? "Hide resolved" : `Show resolved (${resolvedComments.length})`}
          </Button>
        ) : null}
      </div>

      {visibleComments.length > 0 ? (
        <div className="floating-control-frame rounded-xl">
          <div className="overflow-hidden rounded-[calc(var(--radius-xl)-1px)] floating-control-surface divide-y divide-default">
            {visibleComments.map((comment) => (
              <TrailReviewCommentRow
                key={comment.id}
                comment={comment}
                onOpenThread={onOpenThread}
              />
            ))}
          </div>
        </div>
      ) : (
        <div className="rounded-lg bg-floating p-4 text-sm leading-5 text-muted">
          <p>{emptyText}</p>
        </div>
      )}
    </section>
  )
}

