  onOpenThread,
}: {
  comments: TrailComment[]
  onOpenThread: () => void
}) {
  const [showResolved, setShowResolved] = useState(false)
  const unresolvedComments = useMemo(() => comments.filter((comment) => !comment.resolved), [comments])
  const resolvedComments = useMemo(() => comments.filter((comment) => comment.resolved), [comments])
  const visibleComments = showResolved ? comments : unresolvedComments
  const emptyText = comments.length === 0 ? "No review comments yet." : "No unresolved review comments."

  return (
    <section className="space-y-3">
      <div className="flex items-center justify-between gap-3">
        <SectionHeader title="Review comments" count={visibleComments.length} />
        {resolvedComments.length > 0 ? (
          <Button
            size="small"
            variant="ghost"
            condensed
            onClick={() => setShowResolved((value) => !value)}
          >
            {showResolved ? "Hide resolved" : `Show resolved (${resolvedComments.length})`}
          </Button>
        ) : null}
      </div>

      {visibleComments.length > 0 ? (
        <div className="floating-control-frame rounded-xl">
          <div className="overflow-hidden rounded-[calc(var(--radius-xl)-1px)] floating-control-surface divide-y divide-default">
            {visibleComments.map((comment) => (
              <TrailReviewCommentRow
                key={comment.id}
                comment={comment}
                onOpenThread={onOpenThread}
              />
            ))}
          </div>
        </div>
      ) : (
        <div className="rounded-lg bg-floating p-4 text-sm leading-5 text-muted">
          <p>{emptyText}</p>
        </div>
      )}
    </section>
  )
}

function TrailReviewCommentRow({
  comment,
  onOpenThread,
}: {
  comment: TrailComment
  onOpenThread: () => void
}) {
  const replyCount = comment.replies.length

  return (
    <button
      type="button"
      className="flex w-full items-start gap-3 px-4 py-3 text-left list-hover-transition hover:bg-hover focus:outline-none focus-visible:ring-2 focus-visible:ring-focus focus-visible:ring-inset"
      onClick={onOpenThread}
    >
      <GitHubAvatar username={comment.author} className="mt-0.5 size-6 shrink-0" />
      <div className="min-w-0 flex-1 space-y-1">
        <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          <span className="truncate text-sm leading-5 font-medium text-default">
            {comment.author}
          </span>
          <time dateTime={comment.created_at} className="shrink-0 text-xs leading-5 text-muted">
            {formatRelativeTime(comment.created_at)}
          </time>
          {comment.resolved ? <ResolvedCommentBadge /> : null}
        </div>
        <p className="line-clamp-2 text-sm leading-5 text-muted">
          {getReviewCommentPreviewText(comment.body)}
        </p>
        {replyCount > 0 || comment.resolved_by ? (
          <p className="text-xs leading-5 text-muted">
            {replyCount > 0 ? formatReplyCount(replyCount) : null}
            {replyCount > 0 && comment.resolved_by ? " · " : null}
            {comment.resolved_by ? `Resolved by ${comment.resolved_by}` : null}
          </p>
        ) : null}
      </div>
    </button>
  )
}

function ResolvedCommentBadge() {
  return (
    <span className="inline-flex shrink-0 items-center gap-1 rounded bg-neutral-100 px-1.5 py-0.5 text-xs leading-4 font-medium text-muted dark:bg-neutral-800">
      <CheckCircle2 size={12} />
      Resolved
    </span>
  )
}

function getReviewCommentPreviewText(body: string) {
  return body.trim().replace(/\s+/g, " ") || "No comment body."
}

function formatReplyCount(count: number) {
  if (count === 1) return "1 reply"
  return `${count.toLocaleString()} replies`
}

