type TrailLifecycleTone = "success" | "failed" | "pending" | "neutral"

function TrailLifecycleSidebar({
  trail,
  org,
  repo,
  number,
  mergeability,
  onMergeChanges,
  isMerging,
}: {
  trail: TrailDetail
  org: string
  repo: string
  number: number
  mergeability?: TrailMergeability
  onMergeChanges: () => void
  isMerging: boolean
}) {
  const status = getTrailLifecycleSidebarStatus(trail, mergeability)
  const hasAction =
    !!mergeability?.mergeable ||
    (trail.status === "in_review" && deriveReviewStatus(trail.reviewers) !== "approved")

  return (
    <section className="space-y-3">
      <SectionHeader title="Review & merge" />
      <div className="floating-control-frame rounded-xl">
        <div className="space-y-3 rounded-[calc(var(--radius-xl)-1px)] floating-control-surface p-3">
          <div className="flex min-w-0 items-start gap-3">
            <TrailLifecycleStatusIcon tone={status.tone} />
            <div className="min-w-0 flex-1">
              <p className="text-sm leading-5 font-medium text-default">{status.title}</p>
              <p className="text-sm leading-5 text-muted">{status.description}</p>
            </div>
          </div>
          {hasAction ? (
            <TrailPrimaryAction
              trail={trail}
              org={org}
              repo={repo}
              number={number}
              mergeability={mergeability}
              onMergeChanges={onMergeChanges}
              isMerging={isMerging}
              fullWidth
            />
          ) : null}
        </div>
      </div>
    </section>
  )
}

